        overflow: "hidden",
        outline: `1px solid ${borderColor}`,
        outlineOffset: "-1px",
        opacity: flipped ? 0 : 1,
        transition: "opacity 0.5s ease",
        zIndex: 2,
        pointerEvents: flipped ? "none" : "auto",
