    ? {
        position: "absolute",
        inset: 0,
        borderRadius,
        overflow: "hidden",
        background: bgBack,
        outline: `1px solid ${borderColor}`,
        display: "flex",
        flexDirection: isMobile ? "column" : "row",
        backfaceVisibility: "hidden",
        transform: `${flipAxis}(180deg)`,
